<script setup>
import{computed,nextTick,onBeforeUnmount,onMounted,ref,shallowRef}from'vue';
import{birthdayDraft,birthdayFromDraft,convertDraft,createStore,LunarYear,newDraft,ordered,reorder,validateDocument,validateSettings}from'./birthday-model.js';
import balloon from'./original/balloon-0HG1ynQp.png';
const props=defineProps({host:Object,initialSettings:Object,initialDocument:Object});
const settings=ref(validateSettings(props.initialSettings)),document=shallowRef(validateDocument(props.initialDocument)),now=ref(Date.now()),draft=ref({}),themeDraft=ref({}),editor=ref(),confirm=ref(),themeDialog=ref(),editError=ref(''),themeError=ref(''),error=ref(''),saving=ref(false),themeSaving=ref(false),pendingDelete=ref(''),dragged=ref('');
let alive=true,timer;
const store=createStore(document.value,value=>props.host.request('storage.set',value),{preview:props.host.preview,changed:value=>{document.value=value;}});
props.host.beforeLibrarySwitch=async()=>{if(saving.value||themeSaving.value||[editor,confirm,themeDialog].some(dialog=>dialog.value?.open))throw Error('请先保存或关闭生日编辑窗口');await store.flush();};
const birthdays=computed(()=>ordered(document.value,now.value)),theme=computed(()=>({'--widget-background-color':settings.value.background,'--widget-border-radius':'22px'}));
const lunarMonths=computed(()=>{const year=Number(draft.value.year);return Number.isInteger(year)&&year>=1949&&year<=2099?LunarYear.fromYear(year).getMonthsInYear().map(month=>({value:month.getMonth(),label:(month.getMonth()<0?'闰':'')+Math.abs(month.getMonth())+'月'})):[];});
function openNew(){draft.value=newDraft(now.value);editError.value='';editor.value.showModal();}
function openEdit(id){const value=document.value.birthdays.find(item=>item.id===id);if(!value)return;draft.value=birthdayDraft(value);editError.value='';editor.value.showModal();}
function switchDateType(type){try{draft.value=convertDraft(draft.value,type);editError.value='';}catch(reason){editError.value=String(reason?.message||reason);}}
async function saveBirthday(){if(props.host.preview||saving.value)return;saving.value=true;editError.value='';try{const previous=document.value.birthdays.find(item=>item.id===draft.value.id),value=birthdayFromDraft(draft.value,previous,Date.now());await store.update(next=>{const index=next.birthdays.findIndex(item=>item.id===value.id);if(index<0)next.birthdays.push(value);else next.birthdays[index]=value;});if(alive)editor.value.close();}catch(reason){if(alive)editError.value='生日未保存：'+String(reason?.message||reason);}finally{saving.value=false;}}
function askDelete(id){pendingDelete.value=id;error.value='';confirm.value.showModal();}
async function remove(){if(props.host.preview||saving.value)return;saving.value=true;error.value='';try{await store.update(next=>{next.birthdays=next.birthdays.filter(item=>item.id!==pendingDelete.value);});if(alive){confirm.value.close();editor.value?.close();}}catch(reason){if(alive)error.value='删除未保存：'+String(reason?.message||reason);}finally{saving.value=false;}}
async function dropBefore(from,to){if(!from||from===to)return;error.value='';try{await store.update(next=>{Object.assign(next,reorder(next,from,to,now.value));});}catch(reason){if(alive)error.value='排序未保存：'+String(reason?.message||reason);}dragged.value='';}
function dragStart(event,id){if(event.button!==0||props.host.preview)return;dragged.value=id;event.currentTarget.setPointerCapture(event.pointerId);}
function dragEnd(event){const from=dragged.value;if(!from)return;const target=window.document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-birthday-id]');dragged.value='';if(!target||target.dataset.birthdayId===from)return;const bounds=target.getBoundingClientRect(),index=birthdays.value.findIndex(item=>item.id===target.dataset.birthdayId),to=event.clientY<bounds.top+bounds.height/2?target.dataset.birthdayId:birthdays.value[index+1]?.id||'';void dropBefore(from,to);}
function openTheme(){themeDraft.value={...settings.value};themeError.value='';themeDialog.value.showModal();}
async function saveTheme(){if(props.host.preview||themeSaving.value)return;themeSaving.value=true;themeError.value='';try{const next=validateSettings(themeDraft.value);if(!CSS.supports('color',next.background))throw Error('背景颜色无效');const value=validateSettings(await props.host.request('settings.update',next));if(alive){settings.value=value;themeDialog.value.close();}}catch(reason){if(alive)themeError.value='背景未保存：'+String(reason?.message||reason);}finally{themeSaving.value=false;}}
function dispose(){alive=false;clearInterval(timer);store.dispose();}
onBeforeUnmount(dispose);onMounted(async()=>{await props.host.ready();if(!alive)return;timer=setInterval(()=>{now.value=Date.now();},1000);if(!props.host.preview&&new URLSearchParams(location.search).get('verify')==='widgetjs')await verifySession();});
async function verifySession(){
  const prior=document.value.verification,label='生日'+props.host.instanceId.slice(0,8),background='#'+props.host.instanceId.replaceAll('-','').slice(0,6);let invalidSaveRejected=prior?.invalidSaveRejected===true;
  if(!prior?.uiVerified){openNew();await nextTick();draft.value.name='';const before=JSON.stringify((await props.host.request('storage.get')).birthdays||[]);await saveBirthday();invalidSaveRejected=JSON.stringify((await props.host.request('storage.get')).birthdays||[])===before&&editError.value.includes('未保存');draft.value.name=label;const date=new Date();draft.value.date='2000-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');await nextTick();window.document.getElementById('birthday-form').requestSubmit();for(let n=0;n<100&&saving.value;n++)await new Promise(resolve=>setTimeout(resolve,50));if(saving.value||editor.value.open)throw Error('生日表单保存未完成：'+editError.value);openTheme();themeDraft.value.background=background;await saveTheme();}
  await nextTick();const image=window.document.querySelector('.image');if(!image.complete)await new Promise(resolve=>{image.addEventListener('load',resolve,{once:true});image.addEventListener('error',resolve,{once:true});setTimeout(resolve,3000);});
  const saved=await props.host.request('settings.get'),stored=await props.host.request('storage.get'),configurationSaved=stored.birthdays?.some(item=>item.name===label)&&saved.background===background,imagesLoaded=image.complete&&image.naturalWidth>0&&window.document.querySelector('.list.active .right svg')!==null,stylesLoaded=getComputedStyle(window.document.querySelector('.birthday-list-container')).paddingTop==='16px'&&getComputedStyle(window.document.querySelector('.list.active')).backgroundImage.includes('linear-gradient');
  await store.update(next=>{next.verification={uiVerified:configurationSaved&&invalidSaveRejected&&imagesLoaded&&stylesLoaded,configurationSaved,invalidSaveRejected,imagesLoaded,stylesLoaded,savedLabel:label,runtimeLoads:(prior?.runtimeLoads??0)+1,localOnly:true,renderedText:window.document.querySelector('.people-list').textContent.slice(0,500),origin:location.origin};});
}
</script>
<template><main class="widget" :style="theme"><section class="birthday-list-container"><img class="image" :src="balloon" alt=""><header class="title"><span>生日列表</span><button class="add" type="button" aria-label="添加生日" title="添加生日" @click="openNew">＋</button></header><div class="scroll-wrapper"><div class="people-list"><div v-for="item in birthdays" :key="item.id" class="draggable" :data-birthday-id="item.id"><button class="drag-handle" type="button" aria-label="拖动排序" :disabled="host.preview" @pointerdown="dragStart($event,item.id)" @pointerup="dragEnd" @pointercancel="dragged=''">⠿</button><button class="list" type="button" :class="{active:item.today}" :aria-label="'编辑生日 '+item.name" @click="openEdit(item.id)"><div class="left"><div class="name"><div class="name-value">{{item.name}}</div></div><div class="dates"><div v-if="item.dateType===1&&item.lunarText" class="date"><span class="date-type">农</span><span class="date-value">{{item.lunarText}}</span></div><div class="date"><span class="date-type">公</span><span class="date-value">{{item.solarText}}</span></div></div><p v-if="item.error" class="date-error">{{item.error}}</p></div><div class="right" :class="{active:item.today}"><svg v-if="item.today" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-label="今天生日"><path d="M20 21v-8a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8"/><path d="M4 16s.5-1 2-1 2.5 2 4 2 2.5-2 4-2 2.5 2 4 2 2-1 2-1"/><path d="M2 21h20"/><path d="M7 8v3"/><path d="M12 8v3"/><path d="M17 8v3"/><path d="M7 4h.01"/><path d="M12 4h.01"/><path d="M17 4h.01"/></svg><template v-else><div class="qty">{{item.days??'—'}}</div><span class="unit">天</span></template></div></button></div><button v-if="!birthdays.length" class="empty" type="button" @click="openNew">添加生日</button></div></div></section><button class="configure" type="button" aria-label="生日列表设置" title="生日列表设置" @click="openTheme">⚙</button><output class="status" role="status">{{host.preview?'预览 · 不保存':error}}</output>
<dialog ref="editor" @cancel="saving&&$event.preventDefault()"><form id="birthday-form" @submit.prevent="saveBirthday"><h2>{{draft.id?'编辑':'添加'}}生日</h2><label>姓名<input v-model="draft.name" maxlength="120" placeholder="请输入联系人" required></label><label>日期类型<select :value="draft.dateType" @change="switchDateType(Number($event.target.value))"><option :value="0">公历</option><option :value="1">农历</option></select></label><label v-if="draft.dateType===0">出生日期<input v-model="draft.date" type="date" required></label><fieldset v-else><legend>农历出生日期</legend><label>年份<input v-model="draft.year" type="number" min="1949" max="2099" required></label><label>月份<select v-model="draft.month"><option v-for="month in lunarMonths" :key="month.value" :value="month.value">{{month.label}}</option></select></label><label>日<input v-model="draft.dayOfMonth" type="number" min="1" max="30" required></label></fieldset><p class="error" role="status">{{editError}}</p><footer><button v-if="draft.id" type="button" :disabled="saving||host.preview" @click="askDelete(draft.id)">删除</button><button type="button" :disabled="saving" @click="editor.close()">取消</button><button type="submit" :disabled="saving||host.preview">{{saving?'保存中':'保存'}}</button></footer></form></dialog>
<dialog ref="confirm" @cancel="saving&&$event.preventDefault()"><h2>删除生日？</h2><p>此操作删除当前数据源的生日；使用共享库时会影响连接它的实例。</p><p class="error">{{error}}</p><footer><button type="button" :disabled="saving" @click="confirm.close()">取消</button><button type="button" :disabled="saving||host.preview" @click="remove">确认删除</button></footer></dialog>
<dialog ref="themeDialog" @cancel="themeSaving&&$event.preventDefault()"><form @submit.prevent="saveTheme"><h2>生日列表设置</h2><label>背景颜色<input v-model="themeDraft.background" maxlength="80" required aria-label="背景颜色，支持透明度"></label><p class="error" role="status">{{themeError}}</p><footer><button type="button" :disabled="themeSaving" @click="themeDialog.close()">取消</button><button type="submit" :disabled="themeSaving||host.preview">{{themeSaving?'保存中':'保存'}}</button></footer></form></dialog></main></template>
